import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------------------------------------------------------
# CUDA implementation of exact GELU (erf based) for FP16 tensors
# ------------------------------------------------------------------
cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cmath>

#ifndef M_SQRT1_2
#define M_SQRT1_2 0.70710678118654752440f  // 1/sqrt(2)
#endif

__global__ void gelu_kernel(const half* __restrict__ input,
                            half* __restrict__ output,
                            size_t N) {
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N) {
        float x = __half2float(input[idx]);
        // exact GELU: 0.5 * x * (1 + erf(x / sqrt(2)))
        float y = 0.5f * x * (1.0f + erff(x * M_SQRT1_2));
        output[idx] = __float2half(y);
    }
}

torch::Tensor gelu_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == torch::kHalf,
                "input must be of type torch.float16 (half)");
    auto output = torch::empty_like(input);
    const size_t N = input.numel();

    const int threads = 256;
    const int blocks = (N + threads - 1) / threads;

    // launch kernel (no need for AT_DISPATCH since we only support half)
    gelu_kernel<<<blocks, threads>>>(
        reinterpret_cast<const half*>(input.data_ptr()),
        reinterpret_cast<half*>(output.data_ptr()),
        N);

    // check for launch errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch error: ", cudaGetErrorString(err));
    }
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("gelu_cuda", &gelu_cuda, "Exact GELU (FP16, CUDA)");
}
'''

# Compile the extension (the harness supplies the correct C++ standard flags)
gelu_ext = load_inline(name='gelu_ext',
                       cpp_sources='',
                       cuda_sources=cuda_src,
                       functions=['gelu_cuda'],
                       verbose=False)

# ------------------------------------------------------------------
# PyTorch model that uses the custom kernel
# ------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model. Applies exact GELU
    using a custom CUDA kernel that operates on FP16 tensors.
    """
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure contiguous FP16 tensor on CUDA
        if not x.is_cuda:
            raise RuntimeError("ModelNew expects a CUDA tensor")
        if x.dtype != torch.float16:
            x = x.to(dtype=torch.float16)
        if not x.is_contiguous():
            x = x.contiguous()
        return gelu_ext.gelu_cuda(x)

# ------------------------------------------------------------------
# Helper functions matching the reference API
# ------------------------------------------------------------------
